def solve(scores, k):
    import heapq
    top = []
    result = []
    for score in scores:
        if len(top) < k:
            heapq.heappush(top, score)
        elif score > top[0]:
            heapq.heapreplace(top, score)
        result.append(top[0] if len(top) == k else None)
    return result

def solve(nxt, head):
    slow = fast = head
    while fast != -1 and nxt[fast] != -1:
        slow = nxt[slow]
        fast = nxt[nxt[fast]]
        if slow == fast:
            probe = head
            while probe != slow:
                probe = nxt[probe]
                slow = nxt[slow]
            return probe
    return -1

def solve(nodes):
    from collections import deque
    if not nodes:
        return []
    queue = deque([0])
    sums = []
    while queue:
        level_sum = 0
        for _ in range(len(queue)):
            value, left, right = nodes[queue.popleft()]
            level_sum += value
            if left != -1:
                queue.append(left)
            if right != -1:
                queue.append(right)
        sums.append(level_sum)
    return sums

def solve(grid, start, goal):
    from collections import deque
    origin, target = tuple(start), tuple(goal)
    if grid[origin[0]][origin[1]] == "#" or grid[target[0]][target[1]] == "#":
        return -1
    queue = deque([(origin, 0)])
    seen = {origin}
    while queue:
        (r, c), distance = queue.popleft()
        if (r, c) == target:
            return distance
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == "." and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    queue.append(((nr, nc), distance + 1))
    return -1

def solve(n, edges):
    from collections import deque
    children = [[] for _ in range(n)]
    indegree = [0] * n
    for parent, child in edges:
        children[parent].append(child)
        indegree[child] += 1
    ready = deque(i for i in range(n) if indegree[i] == 0)
    done = rounds = 0
    while ready:
        rounds += 1
        for _ in range(len(ready)):
            parent = ready.popleft()
            done += 1
            for child in children[parent]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    ready.append(child)
    return rounds if done == n else -1

def solve(sizes, total):
    impossible = total + 1
    best = [0] + [impossible] * total
    for amount in range(1, total + 1):
        for size in sizes:
            if size <= amount:
                best[amount] = min(best[amount], 1 + best[amount - size])
    return best[total] if best[total] != impossible else -1

def solve(source, target):
    previous = list(range(len(target) + 1))
    for i, src in enumerate(source, start=1):
        current = [i]
        for j, dst in enumerate(target, start=1):
            current.append(min(previous[j] + 1, current[j - 1] + 1,
                               previous[j - 1] + (src != dst)))
        previous = current
    return previous[-1]

def solve(values, width):
    from collections import deque
    candidates = deque()
    peaks = []
    for right, value in enumerate(values):
        while candidates and candidates[0] <= right - width:
            candidates.popleft()
        while candidates and values[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(right)
        if right + 1 >= width:
            peaks.append(values[candidates[0]])
    return peaks

def solve(needs, capacity):
    ordered = sorted(needs)
    left, right = 0, len(ordered) - 1
    best = -1
    while left < right:
        amount = ordered[left] + ordered[right]
        if amount <= capacity:
            best = max(best, amount)
            left += 1
        else:
            right -= 1
    return best

def solve(hours, total):
    ordered = sorted(hours)
    result, path = [], []
    def search(start, remaining):
        if remaining == 0:
            result.append(path.copy())
            return
        for i in range(start, len(ordered)):
            value = ordered[i]
            if value > remaining:
                break
            path.append(value)
            search(i + 1, remaining - value)
            path.pop()
    search(0, total)
    return result

def solve(sessions):
    changes = {}
    for start, end in sessions:
        changes[start] = changes.get(start, 0) + 1
        changes[end] = changes.get(end, 0) - 1
    active = peak = 0
    for time in sorted(changes):
        active += changes[time]
        peak = max(peak, active)
    return peak

def solve(capacity, ops):
    from collections import OrderedDict
    cache = OrderedDict()
    reads = []
    for op in ops:
        key = op[1]
        if op[0] == "put":
            cache[key] = op[2]
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif key in cache:
            cache.move_to_end(key)
            reads.append(cache[key])
        else:
            reads.append(None)
    return reads

