import math
import torch

def solve(logits, token_ids):
    target = token_ids[:, 1:]
    valid = (token_ids[:, :-1] != -100) & (target != -100)
    if not valid.any():
        return logits[..., :0].sum()
    scores = logits[:, :-1][valid]
    dtype = torch.float32 if scores.dtype in (torch.float16, torch.bfloat16) else scores.dtype
    log_probs = scores.log_softmax(dim=-1, dtype=dtype)
    return -log_probs.gather(1, target[valid].unsqueeze(1)).mean()

def solve(events, catalog):
    results = {}
    observations = []
    final = None
    for event in events:
        if event["type"] == "final":
            final = event["text"]
            break
        call_id = event["id"]
        if call_id not in results:
            args = event["args"]
            if event["name"] == "lookup":
                result = catalog.get(args["key"], {"error": "missing_key"})
            elif event["name"] == "sum":
                result = sum(args["values"])
            else:
                result = {"error": "unknown_tool"}
            results[call_id] = result
        observations.append({"id": call_id, "result": results[call_id]})
    return {"observations": observations, "final": final, "executions": len(results)}

def solve(nodes):
    values = []
    for op, *args in nodes:
        if op == "input":
            values.append(args[0])
        else:
            a, b = args
            values.append(values[a] + values[b] if op == "add" else values[a] * values[b])
    gradients = [0.0] * len(nodes)
    gradients[-1] = 1.0
    for i in range(len(nodes) - 1, -1, -1):
        op, *args = nodes[i]
        if op != "input":
            a, b = args
            gradients[a] += gradients[i] * (values[b] if op == "mul" else 1)
            gradients[b] += gradients[i] * (values[a] if op == "mul" else 1)
    return gradients

def solve(points, centers):
    def distance(a, b):
        return sum((x-y)**2 for x, y in zip(a, b))
    labels = [min(range(len(centers)), key=lambda k: distance(row, centers[k]))
              for row in points]
    totals = [[0.0] * len(centers[0]) for _ in centers]
    counts = [0] * len(centers)
    for row, k in zip(points, labels):
        counts[k] += 1
        for j, value in enumerate(row):
            totals[k][j] += value
    updated = [[v / counts[k] for v in totals[k]] if counts[k] else list(old)
               for k, old in enumerate(centers)]
    return [labels, updated, sum(distance(row, updated[k]) for row, k in zip(points, labels))]

def solve(image, kernel, stride, pad):
    channels, h, w = len(image), len(image[0]), len(image[0][0])
    kh, kw = len(kernel[0]), len(kernel[0][0])
    out = []
    for top in range(-pad, h + pad - kh + 1, stride):
        row = []
        for left in range(-pad, w + pad - kw + 1, stride):
            value = 0
            for c in range(channels):
                for dy in range(kh):
                    for dx in range(kw):
                        y, x = top + dy, left + dx
                        if 0 <= y < h and 0 <= x < w:
                            value += image[c][y][x] * kernel[c][dy][dx]
            row.append(value)
        out.append(row)
    return out

from collections import Counter

def merge_once(tokens, pair, new_id):
    out = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens) and (tokens[i], tokens[i+1]) == pair:
            out.append(new_id)
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out

def solve(documents, steps):
    docs = [list(text.encode("utf-8")) for text in documents]
    merges = []
    for _ in range(steps):
        counts = Counter(pair for doc in docs for pair in zip(doc, doc[1:]))
        if not counts:
            break
        pair = min(counts, key=lambda p: (-counts[p], p))
        docs = [merge_once(doc, pair, 256 + len(merges)) for doc in docs]
        merges.append(list(pair))
    return merges

def merge_once(tokens, pair, new_id):
    out = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens) and (tokens[i], tokens[i+1]) == pair:
            out.append(new_id)
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out

def solve(text, merges):
    tokens = list(text.encode("utf-8"))
    for i, pair in enumerate(merges):
        tokens = merge_once(tokens, tuple(pair), 256 + i)
    return tokens

def solve(docs, width, eos, pad):
    rows = []
    for doc_id, doc in enumerate(docs):
        tokens = doc + [eos]
        if not rows or len(rows[-1]["ids"]) + len(tokens) > width:
            rows.append({"ids": [], "seg": [], "pos": [], "labels": []})
        row = rows[-1]
        row["ids"].extend(tokens)
        row["seg"].extend([doc_id] * len(tokens))
        row["pos"].extend(range(len(tokens)))
        row["labels"].extend(tokens[1:] + [-100])
    for row in rows:
        missing = width - len(row["ids"])
        for key, value in (("ids", pad), ("seg", -1), ("pos", 0), ("labels", -100)):
            row[key].extend([value] * missing)
    return rows

