import torch

def solve(x, ids, weights, experts):
    out = torch.zeros_like(x)
    for e, expert in enumerate(experts):
        rows, slots = torch.where(ids == e)
        if rows.numel():
            values = expert(x[rows])
            out = out.index_add(0, rows, values * weights[rows, slots, None])
    return out

