        matched = 0
        for start in range(0, len(prompt)-block_size+1, block_size):
            key = tuple(prompt[start:start+block_size])
            if key in node:
                matched += block_size
            else:
                node[key] = {}
            node = node[key]
        hits.append(matched)
    return hits

