    for block,start in enumerate(range(0,len(x),block_size)):
        subtotal = sum(x[j]*w[j] for j in range(start,min(start+block_size,len(x))))
        answer += subtotal*x_scales[block]*w_scales[block]
    return answer

def solve(requests):
    ttfts, tpots = [], []
    count = 0
    start, end = float('inf'), -float('inf')
    for arrival,tokens in requests:
        ttfts.append(tokens[0]-arrival)
        if len(tokens) > 1:
            tpots.append((tokens[-1]-tokens[0])/(len(tokens)-1))
        count += len(tokens)
        start = min(start,arrival)
        end = max(end,tokens[-1])
    return {"ttft_ms":sum(ttfts)/len(ttfts) if ttfts else None,
            "tpot_ms":sum(tpots)/len(tpots) if tpots else None,
            "tokens_per_s":1000*count/(end-start) if end > start else None}

def solve(hits, k):
    best = {}
    for doc, chunk, score in hits:
        candidate = (-score, chunk)
        if doc not in best or candidate < best[doc]:
            best[doc] = candidate
    ordered = sorted(best, key=lambda doc: (best[doc][0], doc))
    return [[doc, best[doc][1]] for doc in ordered[:k]]

from math import hypot
from heapq import nsmallest

def solve(query, vectors, k):
    qnorm = hypot(*query)
    if qnorm == 0 or k == 0:
        return []
    q = [value / qnorm for value in query]
    def candidates():
        for i, vector in enumerate(vectors):
            norm = hypot(*vector)
            if norm:
                cosine = sum(x * (y / norm) for x, y in zip(q, vector))
                yield (-cosine, i)
    return [i for _, i in nsmallest(k, candidates())]

from collections import defaultdict
from fractions import Fraction

def solve(rankings, c, k):
    scores = defaultdict(Fraction)
    for ranking in rankings:
        for rank, doc in enumerate(dict.fromkeys(ranking), 1):
            scores[doc] += Fraction(1, c + rank)
    return sorted(scores, key=lambda doc: (-scores[doc], doc))[:k]

def solve(relevance, similarity, weight, k):
    count = len(relevance)
    used = [False] * count
    redundancy = [0.0] * count
    result = []
    for step in range(min(k, count)):
        def score(i):
            if step == 0:
                return relevance[i]
            return weight * relevance[i] - (1 - weight) * redundancy[i]
        best = max((i for i in range(count) if not used[i]), key=score)
        used[best] = True
        result.append(best)
        for i in range(count):
            redundancy[i] = max(redundancy[i], similarity[i][best])
    return result

