def solve(flowerbed, n):
    previous = 0
    for i, occupied in enumerate(flowerbed):
        right = flowerbed[i + 1] if i + 1 < len(flowerbed) else 0
        if not occupied and not previous and not right:
            n -= 1
            previous = 1
        else:
            previous = occupied
    return n <= 0

