problems.solution:
def solve(chars):
    read = write = 0
    while read < len(chars):
        end = read + 1
        while end < len(chars) and chars[end] == chars[read]:
            end += 1
        chars[write] = chars[read]
        write += 1
        if end - read > 1:
            count = end - read
            divisor = 1
            while divisor * 10 <= count:
                divisor *= 10
            while divisor:
                chars[write] = str(count // divisor)
                write += 1
                count %= divisor
                divisor //= 10
        read = end
    return write

