problems.solution:
def solve(nums, k):
    waiting = {}
    pairs = 0
    for x in nums:
        partner = k - x
        if waiting.get(partner, 0):
            waiting[partner] -= 1
            pairs += 1
        else:
            waiting[x] = waiting.get(x, 0) + 1
    return pairs

