def solve(asteroids):
    survivors = []
    for x in asteroids:
        while survivors and survivors[-1] > 0 > x:
            if survivors[-1] < -x:
                survivors.pop()
                continue
            if survivors[-1] == -x:
                survivors.pop()
            break
        else:
            survivors.append(x)
    return survivors

