problems.solution:
def solve(s):
    stack = []
    pieces = []
    count = 0
    for char in s:
        if char.isdigit():
            count = count * 10 + int(char)
        elif char == "[":
            stack.append((pieces, count))
            pieces, count = [], 0
        elif char == "]":
            prefix, repetitions = stack.pop()
            prefix.append("".join(pieces) * repetitions)
            pieces = prefix
        else:
            pieces.append(char)
    return "".join(pieces)

