def solve(isConnected):
    visited = set()
    count = 0
    for start in range(len(isConnected)):
        if start in visited:
            continue
        count += 1
        visited.add(start)
        stack = [start]
        while stack:
            node = stack.pop()
            for neighbor, linked in enumerate(isConnected[node]):
                if linked and neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
    return count

