problems.solution:
def solve(n, connections):
    graph = [[] for _ in range(n)]
    for u, v in connections:
        graph[u].append((v, 1))
        graph[v].append((u, 0))
    answer = 0
    stack = [(0, -1)]
    while stack:
        u, parent = stack.pop()
        for v, outward in graph[u]:
            if v != parent:
                answer += outward
                stack.append((v, u))
    return answer

