def solve(nums1, nums2, k):
    import heapq
    heap = []
    subtotal = best = 0
    for y, x in sorted(zip(nums2, nums1), reverse=True):
        heapq.heappush(heap, x)
        subtotal += x
        if len(heap) > k:
            subtotal -= heapq.heappop(heap)
        if len(heap) == k:
            best = max(best, subtotal * y)
    return best

