problems.solution:
def solve(costs, k, candidates):
    import heapq
    left, right = 0, len(costs) - 1
    heap = []
    for _ in range(candidates):
        if left > right:
            break
        heapq.heappush(heap, (costs[left], left, 0))
        left += 1
    for _ in range(candidates):
        if left > right:
            break
        heapq.heappush(heap, (costs[right], right, 1))
        right -= 1
    total = 0
    for _ in range(k):
        cost, _, side = heapq.heappop(heap)
        total += cost
        if left <= right:
            if side == 0:
                heapq.heappush(heap, (costs[left], left, 0))
                left += 1
            else:
                heapq.heappush(heap, (costs[right], right, 1))
                right -= 1
    return total

