problems.solution:
def solve(text1, text2):
    if len(text2) > len(text1):
        text1, text2 = text2, text1
    row = [0] * (len(text2) + 1)
    for a in text1:
        diagonal = 0
        for j, b in enumerate(text2, 1):
            previous = row[j]
            if a == b:
                row[j] = diagonal + 1
            else:
                row[j] = max(row[j], row[j - 1])
            diagonal = previous
    return row[-1]

