def solve(temperatures):
    result = [0] * len(temperatures)
    waiting = []
    for i, temp in enumerate(temperatures):
        while waiting and temperatures[waiting[-1]] < temp:
            j = waiting.pop()
            result[j] = i - j
        waiting.append(i)
    return result

