def solve(nums):
    nums = sorted(nums)
    answer = []
    for i, a in enumerate(nums):
        if a > 0:
            break
        if i and a == nums[i - 1]:
            continue
        left, right = i + 1, len(nums) - 1
        while left < right:
            total = a + nums[left] + nums[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                b, c = nums[left], nums[right]
                answer.append([a, b, c])
                while left < right and nums[left] == b:
                    left += 1
                while left < right and nums[right] == c:
                    right -= 1
    return answer

