def solve(s, p):
    target = [0] * 26
    current = [0] * 26
    index = lambda c: ord(c) - ord("a")
    for ch in p:
        target[index(ch)] += 1
    result = []
    for i, ch in enumerate(s):
        current[index(ch)] += 1
        if i >= len(p):
            current[index(s[i - len(p)])] -= 1
        if i + 1 >= len(p) and current == target:
            result.append(i + 1 - len(p))
    return result

