from collections import deque

def solve(nums, k):
    queue = deque()
    out = []
    for i, value in enumerate(nums):
        while queue and queue[0] <= i - k:
            queue.popleft()
        while queue and nums[queue[-1]] <= value:
            queue.pop()
        queue.append(i)
        if i >= k - 1:
            out.append(nums[queue[0]])
    return out

