def solve(candidates, target):
    values = sorted(candidates)
    result, path = [], []
    def search(start, left):
        if left == 0:
            result.append(path.copy())
            return
        for i in range(start, len(values)):
            if values[i] > left:
                break
            path.append(values[i])
            search(i, left - values[i])
            path.pop()
    search(0, target)
    return result

