def solve(s):
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(i, n):
            pal[i][j] = s[i] == s[j] and (j-i < 2 or pal[i+1][j-1])
    answer, path = [], []
    def visit(i):
        if i == n:
            answer.append(path.copy())
            return
        for j in range(i, n):
            if pal[i][j]:
                path.append(s[i:j+1])
                visit(j+1)
                path.pop()
    visit(0)
    return answer

