problems.solution:
def solve(nums1, nums2):
    a, b = sorted((nums1, nums2), key=len)
    m, n = len(a), len(b)
    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2
        j = (m + n + 1) // 2 - i
        al = a[i-1] if i else float('-inf')
        ar = a[i] if i < m else float('inf')
        bl = b[j-1] if j else float('-inf')
        br = b[j] if j < n else float('inf')
        if al > br:
            hi = i - 1
        elif bl > ar:
            lo = i + 1
        elif (m+n) % 2:
            return max(al, bl)
        else:
            return (max(al, bl) + min(ar, br)) / 2

