problems.solution:
def solve(heights):
    stack = []
    best = 0
    for right in range(len(heights) + 1):
        height = heights[right] if right < len(heights) else 0
        start = right
        while stack and stack[-1][1] > height:
            start, old = stack.pop()
            best = max(best, old * (right-start))
        if not stack or stack[-1][1] < height:
            stack.append((start, height))
    return best

