problems.solution:
def solve(s, wordDict):
    words = set(wordDict)
    lengths = sorted({len(word) for word in words})
    good = [True] + [False] * len(s)
    for end in range(1,len(s)+1):
        for length in lengths:
            start = end-length
            if start < 0:
                break
            if good[start] and s[start:end] in words:
                good[end] = True
                break
    return good[-1]

