problems.solution:
def solve(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    possible = [True] + [False]*target
    for value in nums:
        for s in range(target, value-1, -1):
            possible[s] |= possible[s-value]
    return possible[target]

