def solve(s):
    begin, length = 0, 1
    for center in range(len(s)):
        for right in (center, center+1):
            left = center
            while left >= 0 and right < len(s) and s[left] == s[right]:
                if right-left+1 > length:
                    begin, length = left, right-left+1
                left -= 1
                right += 1
    return s[begin:begin+length]

