def solve(gas, cost):
    total = tank = start = 0
    for i, (fuel, charge) in enumerate(zip(gas, cost)):
        delta = fuel-charge
        total += delta
        tank += delta
        if tank < 0:
            start = i+1
            tank = 0
    return start if total >= 0 else -1

