def solve(ratings):
    sweets = [1]*len(ratings)
    for i in range(1,len(ratings)):
        if ratings[i] > ratings[i-1]:
            sweets[i] = sweets[i-1]+1
    for i in range(len(ratings)-2,-1,-1):
        if ratings[i] > ratings[i+1]:
            sweets[i] = max(sweets[i], sweets[i+1]+1)
    return sum(sweets)

