problems.solution:
def solve(haystack, needle):
    if not needle:
        return 0
    prefix = [0] * len(needle)
    j = 0
    for i in range(1, len(needle)):
        while j and needle[i] != needle[j]:
            j = prefix[j-1]
        if needle[i] == needle[j]:
            j += 1
        prefix[i] = j
    j = 0
    for i, ch in enumerate(haystack):
        while j and needle[j] != ch:
            j = prefix[j-1]
        if needle[j] == ch:
            j += 1
        if j == len(needle):
            return i-j+1
    return -1

