def solve(board):
    seen = set()
    for r, row in enumerate(board):
        for c, value in enumerate(row):
            if value == '.':
                continue
            for key in (('r',r,value), ('c',c,value), ('b',r//3,c//3,value)):
                if key in seen:
                    return False
                seen.add(key)
    return True

