def solve(board):
    m, n = len(board), len(board[0])
    for i in range(m):
        for j in range(n):
            total = sum(board[r][c] & 1 for r in range(max(0,i-1),min(m,i+2))
                        for c in range(max(0,j-1),min(n,j+2)) if (r,c)!=(i,j))
            if total == 3 or (board[i][j] & 1 and total == 2):
                board[i][j] |= 2
    for row in board:
        for j in range(n):
            row[j] >>= 1

