problems.solution:
def solve(s):
    total, sign, number = 0, 1, 0
    stack = []
    for ch in s:
        if ch.isdigit():
            number = number*10 + int(ch)
        elif ch in '+-':
            total += sign * number
            number = 0
            sign = 1 if ch == '+' else -1
        elif ch == '(':
            stack.append((total, sign))
            total, sign, number = 0, 1, 0
        elif ch == ')':
            total += sign * number
            outer, direction = stack.pop()
            total, sign, number = outer + direction*total, 1, 0
    return total + sign*number

