problems.solution:
def solve(head):
    dummy = ListNode(0,head)
    keep = dummy
    while head:
        end = head
        while end.next and end.next.val == head.val:
            end = end.next
        if end is head:
            keep = head
        else:
            keep.next = end.next
        head = end.next
    return dummy.next

