problems.solution:
def solve(p, q):
    stack = [(p,q)]
    while stack:
        a, b = stack.pop()
        if a is None or b is None:
            if a is not b:
                return False
        else:
            if a.val != b.val:
                return False
            stack.extend([(a.left,b.left),(a.right,b.right)])
    return True

