problems.solution:
def solve(inorder, postorder):
    if not postorder:
        return None
    root = TreeNode(postorder[-1])
    stack = [root]
    i = len(inorder)-1
    for value in reversed(postorder[:-1]):
        child = TreeNode(value)
        if stack[-1].val != inorder[i]:
            stack[-1].right = child
        else:
            while stack and stack[-1].val == inorder[i]:
                parent = stack.pop()
                i -= 1
            parent.left = child
        stack.append(child)
    return root

