problems.solution:
def solve(root):
    def left_depth(node):
        depth = 0
        while node:
            depth += 1
            node = node.left
        return depth
    count = 0
    while root:
        a, b = left_depth(root.left), left_depth(root.right)
        if a == b:
            count += 1 << a
            root = root.right
        else:
            count += 1 << b
            root = root.left
    return count

