def solve(root):
    stack = []
    previous, best = None, float('inf')
    while stack or root:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        if previous is not None:
            best = min(best,root.val-previous)
        previous = root.val
        root = root.right
    return best

