def solve(board):
    from collections import deque
    m, n = len(board), len(board[0])
    queue = deque()
    def keep(i,j):
        if 0 <= i < m and 0 <= j < n and board[i][j] == 'O':
            board[i][j] = '#'
            queue.append((i,j))
    for i in range(m):
        keep(i,0)
        keep(i,n-1)
    for j in range(n):
        keep(0,j)
        keep(m-1,j)
    while queue:
        i,j = queue.popleft()
        for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)):
            keep(a,b)
    for row in board:
        for j, val in enumerate(row):
            row[j] = 'O' if val == '#' else 'X'

