def solve(node):
    from collections import deque
    if node is None:
        return None
    copies = {node: Node(node.val)}
    queue = deque([node])
    while queue:
        current = queue.popleft()
        for other in current.neighbors:
            if other not in copies:
                copies[other] = Node(other.val)
                queue.append(other)
            copies[current].neighbors.append(copies[other])
    return copies[node]

