def solve(board, words):
    root = {}
    for word in words:
        node = root
        for c in word:
            node = node.setdefault(c,{})
        node['#'] = word
    m, n = len(board), len(board[0])
    answer = []
    def visit(i,j,parent):
        c = board[i][j]
        if c not in parent:
            return
        node = parent[c]
        if '#' in node:
            answer.append(node.pop('#'))
        board[i][j] = '!'
        for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)):
            if 0 <= a < m and 0 <= b < n:
                visit(a,b,node)
        board[i][j] = c
        if not node:
            del parent[c]
    for i in range(m):
        for j in range(n):
            visit(i,j,root)
    return answer

