problems.solution:
def solve(k, w, profits, capital):
    import heapq
    projects = sorted(zip(capital,profits))
    options = []
    i = 0
    for _ in range(min(k,len(projects))):
        while i < len(projects) and projects[i][0] <= w:
            heapq.heappush(options,-projects[i][1])
            i += 1
        if not options:
            break
        w -= heapq.heappop(options)
    return w

