problems.solution:
def solve(a, b):
    i, j, carry = len(a)-1, len(b)-1, 0
    digits = []
    while i >= 0 or j >= 0 or carry:
        if i >= 0:
            carry += int(a[i])
            i -= 1
        if j >= 0:
            carry += int(b[j])
            j -= 1
        carry, bit = divmod(carry,2)
        digits.append(str(bit))
    return ''.join(reversed(digits))

