problems.solution:
def solve(points):
    from math import gcd
    best = 1
    for i,(x,y) in enumerate(points):
        counts = {}
        for j in range(i+1,len(points)):
            a,b = points[j]
            dx,dy = a-x,b-y
            divisor = gcd(dx,dy)
            dx,dy = dx//divisor,dy//divisor
            if dx < 0 or (dx == 0 and dy < 0):
                dx,dy = -dx,-dy
            key = dx,dy
            counts[key] = counts.get(key,0)+1
            best = max(best,counts[key]+1)
    return best

