def solve(obstacleGrid):
    dp = [0]*len(obstacleGrid[0])
    dp[0] = 1
    for row in obstacleGrid:
        for j,blocked in enumerate(row):
            if blocked:
                dp[j] = 0
            elif j:
                dp[j] += dp[j-1]
    return dp[-1]

