problems.solution:
def solve(nums):
    buf = [0] * len(nums)
    def count(lo, hi):
        if hi - lo < 2:
            return 0
        mid = (lo + hi) // 2
        total = count(lo, mid) + count(mid, hi)
        i, j = lo, mid
        for out in range(lo, hi):
            if j == hi or (i < mid and nums[i] <= nums[j]):
                buf[out] = nums[i]
                i += 1
            else:
                buf[out] = nums[j]
                j += 1
                total += mid - i
        nums[lo:hi] = buf[lo:hi]
        return total
    return count(0, len(nums)) % 1000000007

