class Codec:
    def serialize(self, root):
        stack, data = [root], []
        while stack:
            node = stack.pop()
            if node is None:
                data.append("#")
            else:
                data.append(str(node.val))
                stack.extend((node.right, node.left))
        return ",".join(data)

    def deserialize(self, text):
        tokens = iter(text.split(","))
        def node(token):
            return None if token == "#" else TreeNode(int(token))
        root = node(next(tokens))
