def solve(preorder, inorder):
    index = {v: i for i, v in enumerate(inorder)}
    view, stack = [], [(0, 0, len(inorder), 0)]
    while stack:
        start, lo, hi, depth = stack.pop()
        if lo == hi:
            continue
        root = preorder[start]
        if depth == len(view):
            view.append(root)
        mid = index[root]
        stack.append((start + 1, lo, mid, depth + 1))
        stack.append((start + 1 + mid - lo, mid + 1, hi, depth + 1))
    return view

