class MinStack:
    def __init__(self):
        self.stack = []

    def push(self, x):
        minimum = min(x, self.min()) if self.stack else x
        self.stack.append((x, minimum))

    def pop(self):
        self.stack.pop()

    def top(self):
        return self.stack[-1][0]

    def min(self):
        return self.stack[-1][1]

