from collections import deque

def solve(nums, size):
    if size <= 0 or size > len(nums):
        return []
    queue, result = deque(), []
    for i, x in enumerate(nums):
        if queue and queue[0] <= i - size:
            queue.popleft()
        while queue and nums[queue[-1]] <= x:
            queue.pop()
        queue.append(i)
        if i >= size - 1:
            result.append(nums[queue[0]])
    return result

