from random import randrange

def solve(nums, n, k):
    target, left, right = k - 1, 0, n - 1
    while left <= right:
        pivot = nums[randrange(left, right + 1)]
        high, i, low = left, left, right
        while i <= low:
            if nums[i] > pivot:
                nums[i], nums[high] = nums[high], nums[i]
                high += 1
                i += 1
            elif nums[i] < pivot:
                nums[i], nums[low] = nums[low], nums[i]
                low -= 1
            else:
                i += 1
        if target < high:
            right = high - 1
        elif target > low:
            left = low + 1
        else:
            return pivot

