problems.solution:
def solve(text):
    numbers, ops = [], []
    priority = {"+": 1, "-": 1, "*": 2, "neg": 3, "pos": 3}
    def apply():
        op = ops.pop()
        b = numbers.pop()
        if op in ("neg", "pos"):
            numbers.append(-b if op == "neg" else b)
        else:
            a = numbers.pop()
            numbers.append(a + b if op == "+" else a - b if op == "-" else a * b)
    i, expecting = 0, True
    while i < len(text):
        char = text[i]
        if char.isspace():
            i += 1
            continue
        if char.isdigit():
            start = i
            while i < len(text) and text[i].isdigit():
                i += 1
            numbers.append(int(text[start:i]))
            expecting = False
            continue
        if char == "(":
            ops.append(char)
            expecting = True
        elif char == ")":
            while ops[-1] != "(":
                apply()
            ops.pop()
            expecting = False
        elif expecting and char in "+-":
            ops.append("neg" if char == "-" else "pos")
        else:
            while ops and ops[-1] != "(" and priority[ops[-1]] >= priority[char]:
                apply()
            ops.append(char)
            expecting = True
        i += 1
    while ops:
        apply()
    return numbers[0]

