def solve(nums):
    result, path = [], []
    used = [False] * len(nums)
    def visit():
        if len(path) == len(nums):
            result.append(path.copy())
            return
        for i, x in enumerate(nums):
            if not used[i]:
                used[i] = True
                path.append(x)
                visit()
                path.pop()
                used[i] = False
    visit()
    return result

