problems.solution:
def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != '1':
                continue
            count += 1
            stack = [(i, j)]
            grid[i][j] = '0'
            while stack:
                r, c = stack.pop()
                for a, b in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if 0 <= a < rows and 0 <= b < cols and grid[a][b] == '1':
                        grid[a][b] = '0'
                        stack.append((a, b))
    return count

