from collections import Counter

def solve(text):
    counts, prefix, out = Counter(text), [], []
    def visit():
        if len(prefix) == len(text):
            out.append("".join(prefix))
            return
        for ch in counts:
            if counts[ch]:
                counts[ch] -= 1
                prefix.append(ch)
                visit()
                prefix.pop()
                counts[ch] += 1
    visit()
    return out

