problems.solution:
def solve(n):
    full = (1 << n)-1
    def count(cols, down, up):
        if cols == full:
            return 1
        choices = full & ~(cols | down | up)
        result = 0
        while choices:
            bit = choices & -choices
            choices -= bit
            result += count(cols|bit, ((down|bit)<<1)&full, (up|bit)>>1)
        return result
    return count(0,0,0)

