problems.solution:
def solve(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n+1) for _ in range(m+1)]
    for i, x in enumerate(a, 1):
        for j, y in enumerate(b, 1):
            dp[i][j] = dp[i-1][j-1]+1 if x == y else max(dp[i-1][j], dp[i][j-1])
    i, j, chars = m, n, []
    while i and j:
        if a[i-1] == b[j-1]:
            chars.append(a[i-1])
            i, j = i-1, j-1
        elif dp[i-1][j] >= dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(chars)) if chars else "-1"

