def run_case(args):
    return solve(*args)

def accepts(args, actual, expected):
    if expected == "-1":
        return actual == "-1"
    if not isinstance(actual, str) or len(actual) != len(expected):
        return False
    for text in args:
        stream = iter(text)
        if not all(ch in stream for ch in actual):
            return False
    return True

