problems.solution:
def solve(digits):
    result, parts = [], []
    def visit(i):
        remaining = 4 - len(parts)
        if not (remaining <= len(digits) - i <= 3 * remaining):
            return
        if remaining == 0:
            result.append(".".join(parts))
            return
        for end in range(i+1, min(i+3,len(digits))+1):
            part = digits[i:end]
            if (len(part) > 1 and part[0] == "0") or int(part) > 255:
                break
            parts.append(part)
            visit(end)
            parts.pop()
    visit(0)
    return result

