problems.solution:
def solve(text, pattern):
    n = len(pattern)
    prev = [False] * (n + 1)
    prev[0] = True
    for j in range(2, n + 1):
        prev[j] = pattern[j-1] == "*" and prev[j-2]
    for ch in text:
        curr = [False] * (n + 1)
        for j in range(1, n + 1):
            p = pattern[j-1]
            if p == "*":
                curr[j] = curr[j-2] or (pattern[j-2] in (ch, ".") and prev[j])
            else:
                curr[j] = prev[j-1] and p in (ch, ".")
        prev = curr
    return prev[n]

