problems.solution:
def solve(nums):
    if len(nums) < 2:
        return sum(nums)
    def linear(start, end):
        older = newer = 0
        for i in range(start, end):
            older, newer = newer, max(newer, older + nums[i])
        return newer
    return max(linear(0, len(nums)-1), linear(1, len(nums)))

