def solve(address):
    v4 = address.split(".")
    if len(v4) == 4 and all(1 <= len(s) <= 3 and all(c in "0123456789" for c in s)
                             and (len(s) == 1 or s[0] != "0") and int(s) <= 255 for s in v4):
        return "IPv4"
    v6 = address.split(":")
    if len(v6) == 8 and all(1 <= len(s) <= 4 and all(c in "0123456789abcdefABCDEF" for c in s) for s in v6):
        return "IPv6"
    return "Neither"

