problems.solution:
def solve(a, m, b, n):
    i, j, out = m-1, n-1, m+n-1
    while j >= 0:
        if i >= 0 and a[i] > b[j]:
            a[out] = a[i]
            i -= 1
        else:
            a[out] = b[j]
            j -= 1
        out -= 1

