problems.solution:
def solve(intervals):
    merged = []
    for current in sorted(intervals, key=lambda x: x.start):
        if merged and current.start <= merged[-1].end:
            merged[-1].end = max(merged[-1].end, current.end)
        else:
            merged.append(current)
    return merged

