from collections import Counter

def solve(s, t):
    need = Counter(t)
    missing = len(t)
    left, best_start, best_size = 0, 0, len(s) + 1
    for right, char in enumerate(s):
        if need[char] > 0:
            missing -= 1
        need[char] -= 1
        while missing == 0:
            size = right - left + 1
            if size < best_size:
                best_start, best_size = left, size
            first = s[left]
            left += 1
            need[first] += 1
            if need[first] > 0:
                missing += 1
    return "" if best_size > len(s) else s[best_start:best_start + best_size]

