problems.solution:
def solve(n, m, nums):
    if n == 0:
        return nums
    k = m % n
    def reverse(a, b):
        while a < b:
            nums[a], nums[b] = nums[b], nums[a]
            a, b = a+1, b-1
    reverse(0,n-1)
    reverse(0,k-1)
    reverse(k,n-1)
    return nums

