problems.driver:
def run_case(args):
    ops, values, capacity = args
    cache, result = Solution(capacity), []
    for op, parameters in zip(ops, values):
        if op == "get":
            value = cache.get(*parameters)
            if type(value) != int:
                raise TypeError("get 应返回整数")
            result.append(str(value))
        else:
            cache.set(*parameters)
            result.append("null")
    return result

