problems.solution:
from collections import OrderedDict

def solve(operations, capacity):
    values, freq, buckets = {}, {}, {}
    minimum, answers = 0, []
    def touch(key):
        nonlocal minimum
        f = freq[key]
        del buckets[f][key]
        if not buckets[f]:
            del buckets[f]
            if minimum == f:
                minimum += 1
        freq[key] = f + 1
        buckets.setdefault(f+1, OrderedDict())[key] = None
    for op in operations:
        mode, key = op[:2]
        if mode == 2:
            answers.append(values.get(key, -1))
            if key in values:
                touch(key)
        elif key in values:
            touch(key)
            values[key] = op[2]
        elif capacity:
            if len(values) == capacity:
                victim, _ = buckets[minimum].popitem(last=False)
                if not buckets[minimum]:
                    del buckets[minimum]
                del values[victim], freq[victim]
            values[key], freq[key], minimum = op[2], 1, 1
            buckets.setdefault(1, OrderedDict())[key] = None
    return answers

